P={(0,1),(1,1),(2,0),(2,1),(3,0),(3,1),(3,2),(3,3),(4,2)}
Q={(0,0),(1,0),(1,1),(1,2),(2,1),(3,2)}
for refl in [False,True]:
 for k in range(4):
  p=set()
  for r,c in P:
   if refl:c=-c
   for _ in range(k):r,c=c,-r
   p.add((r,c))
  mr=min(x for x,y in p);mc=min(y for x,y in p);p={(x-mr,y-mc) for x,y in p}
  # find Q subset congruent within translations
  for r in range(5):
   for c in range(5):
    q={(x+r,y+c) for x,y in Q}
    if q<=p: print('subset',refl,k,sorted(q))
